static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
  // Initialize y to zero
  for (i = 0; i < _PB_N; i++)
    y[i] = 0;

  for (i = 0; i < _PB_M; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);

#if defined(__riscv_vector)
      // Vectorized dot product: tmp[i] = sum(A[i][j] * x[j])
      size_t vl;
      vfloat32m1_t v_tmp = __riscv_vfmv_v_f(SCALAR_VAL(0.0), 1);
      size_t idx = 0;

      while (idx < _PB_N) {
        vl = __riscv_vsetvl_e32m1(_PB_N - idx);
        vfloat32m1_t v_a_row = __riscv_vle32_vf(&A[i][idx], vl);
        vfloat32m1_t v_x = __riscv_vle32_vf(&x[idx], vl);
        vfloat32m1_t v_prod = __riscv_vfmul_vv(v_a_row, v_x, vl);
        v_tmp = __riscv_vfredosum_vs(v_tmp, v_prod, vl);
        idx += vl;
      }
      tmp[i] = __riscv_vfmv_f_s(v_tmp);
#else
      for (j = 0; j < _PB_N; j++)
	tmp[i] = tmp[i] + A[i][j] * x[j];
#endif

#if defined(__riscv_vector)
      // Vectorized update: y[j] = y[j] + A[i][j] * tmp[i]
      idx = 0;

      while (idx < _PB_N) {
        vl = __riscv_vsetvl_e32m1(_PB_N - idx);
        vfloat32m1_t v_a_row = __riscv_vle32_vf(&A[i][idx], vl);
        vfloat32m1_t v_y = __riscv_vle32_vf(&y[idx], vl);
        vfloat32m1_t v_prod = __riscv_vfmul_vf(v_a_row, tmp[i], vl);
        vfloat32m1_t v_y_new = __riscv_vfadd_vv(v_y, v_prod, vl);
        __riscv_vse32_vf(v_y_new, &y[idx], vl);
        idx += vl;
      }
#else
      for (j = 0; j < _PB_N; j++)
	y[j] = y[j] + A[i][j] * tmp[i];
#endif
    }
#pragma endscop

}

