static
void kernel_bicg(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_M; i++)
    s[i] = 0;

  #if defined(__riscv_vector)
  {
    // Initialize s to zero using vector if possible
    size_t vl_m = __riscv_vsetvl_e32m1(_PB_M);
    vfloat32m1_t zero_vec = __riscv_vfmv_v_f(0.0f);

    // Store zeros to s
    __riscv_vse32_v_f32m1(s, zero_vec, vl_m);

    for (i = 0; i < _PB_N; i++) {
      q[i] = SCALAR_VAL(0.0);

      float r_i = r[i];

      // Process in chunks of M
      for (j = 0; j < _PB_M; j += vl_m) {
        size_t vl = __riscv_vsetvl_e32m1(_PB_M - j);

        // Load A[i][j:j+vl]
        vfloat32m1_t a_row = __riscv_vle32_v_f32m1(&A[i][j], vl);

        // Load current s[j:j+vl]
        vfloat32m1_t s_curr = __riscv_vle32_v_f32m1(&s[j], vl);

        // Compute s[j] = s[j] + r[i] * A[i][j]
        vfloat32m1_t term_s = __riscv_vfmul_vf(a_row, r_i, vl);
        vfloat32m1_t s_new = __riscv_vfadd_vv(s_curr, term_s, vl);
        __riscv_vse32_v_f32m1(&s[j], s_new, vl);

        // Load p[j:j+vl]
        vfloat32m1_t p_chunk = __riscv_vle32_v_f32m1(&p[j], vl);

        // Compute q[i] += A[i][j] * p[j]
        vfloat32m1_t term_q = __riscv_vfmul_vv(a_row, p_chunk, vl);
        float q_acc = __riscv_vfredosum_f32_v(term_q, vl);
        q[i] += q_acc;
      }
    }
  }
  #else
  for (i = 0; i < _PB_N; i++)
    {
      q[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_M; j++)
	{
	  s[j] = s[j] + r[i] * A[i][j];
	  q[i] = q[i] + A[i][j] * p[j];
	}
    }
  #endif
#pragma endscop

}

