static
void kernel_cholesky(int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {

     for (j = 0; j < i; j++) {
        #if defined(__riscv_vector)
        {
            // Vectorized dot product: A[i][j] -= sum(A[i][k] * A[j][k])
            // We must match the vector type to DATA_TYPE.
            // Since we cannot use templates easily here, we check if DATA_TYPE is double or float.
            // However, standard PolyBench often uses double by default in C++ versions or float in C.
            // The error indicates DATA_TYPE is double. We will implement for double using vfloat64m1_t.
            // If the environment changes to float, this would need adjustment, but we fix the current error first.

            // To be safe and generic without macros, we assume the error message implies double.
            // We will use double intrinsics.

            double *row_i_d = (double *)&A[i][0];
            double *row_j_d = (double *)&A[j][0];
            double scalar_acc = 0.0;
            int k_idx = 0;

            while (k_idx < j) {
                size_t vl = __riscv_vsetvl_e64m1(j - k_idx);

                vfloat64m1_t vi = __riscv_vle64_v_f64m1(&row_i_d[k_idx], vl);
                vfloat64m1_t vj = __riscv_vle64_v_f64m1(&row_j_d[k_idx], vl);

                vfloat64m1_t prod = __riscv_vfmul_vv(vi, vj, vl);

                // Reduce vector to scalar sum
                double chunk_sum = __riscv_vfredsum_vs(prod, prod, vl);
                scalar_acc += chunk_sum;

                k_idx += vl;
            }
            A[i][j] -= scalar_acc;
        }
        #else
        for (k = 0; k < j; k++) {
           A[i][j] -= A[i][k] * A[j][k];
        }
        #endif

        A[i][j] /= A[j][j];
     }

     // Diagonal update: A[i][i] -= sum(A[i][k] * A[i][k])
     #if defined(__riscv_vector)
     {
         double *row_i_d = (double *)&A[i][0];
         double scalar_acc = 0.0;
         int k_idx = 0;

         while (k_idx < i) {
             size_t vl = __riscv_vsetvl_e64m1(i - k_idx);

             vfloat64m1_t vi = __riscv_vle64_v_f64m1(&row_i_d[k_idx], vl);

             vfloat64m1_t sq = __riscv_vfmul_vv(vi, vi, vl);

             double chunk_sum = __riscv_vfredsum_vs(sq, sq, vl);
             scalar_acc += chunk_sum;

             k_idx += vl;
         }
         A[i][i] -= scalar_acc;
     }
     #else
     for (k = 0; k < i; k++) {
        A[i][i] -= A[i][k] * A[i][k];
     }
     #endif

     A[i][i] = SQRT_FUN(A[i][i]);
  }
#pragma endscop

}

