static
void kernel_deriche(int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h)) {
    int i,j;
    DATA_TYPE xm1, tm1, ym1, ym2;
    DATA_TYPE xp1, xp2;
    DATA_TYPE tp1, tp2;
    DATA_TYPE yp1, yp2;

    DATA_TYPE k;
    DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
    DATA_TYPE b1, b2, c1, c2;

#pragma scop
   k = (SCALAR_VAL(1.0)-EXP_FUN(-alpha))*(SCALAR_VAL(1.0)-EXP_FUN(-alpha))/(SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*alpha*EXP_FUN(-alpha)-EXP_FUN(SCALAR_VAL(2.0)*alpha));
   a1 = a5 = k;
   a2 = a6 = k*EXP_FUN(-alpha)*(alpha-SCALAR_VAL(1.0));
   a3 = a7 = k*EXP_FUN(-alpha)*(alpha+SCALAR_VAL(1.0));
   a4 = a8 = -k*EXP_FUN(SCALAR_VAL(-2.0)*alpha);
   b1 =  POW_FUN(SCALAR_VAL(2.0),-alpha);
   b2 = -EXP_FUN(SCALAR_VAL(-2.0)*alpha);
   c1 = c2 = 1;

   // Forward pass along columns (j loop inside)
   for (i=0; i<_PB_W; i++) {
        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);
        xm1 = SCALAR_VAL(0.0);

        #if defined(__riscv_vector)
        size_t vl;
        vfloat32m1_t v_ym1 = __riscv_vfmv_f_v(ym1);
        vfloat32m1_t v_ym2 = __riscv_vfmv_f_v(ym2);
        vfloat32m1_t v_xm1 = __riscv_vfmv_f_v(xm1);

        int j_vec = 0;
        while (j_vec < _PB_H) {
            vl = __riscv_vsetvl_e32m1(_PB_H - j_vec);

            // Load imgIn[i][j_vec:j_vec+vl]
            vfloat32m1_t v_img = __riscv_vle32_vf(&imgIn[i][j_vec], vl);

            // Compute: y1 = a1*img + a2*xm1 + b1*ym1 + b2*ym2
            vfloat32m1_t t1 = __riscv_vfmul_vf(v_img, a1, vl);
            vfloat32m1_t t2 = __riscv_vfmul_vf(v_xm1, a2, vl);
            vfloat32m1_t t3 = __riscv_vfmul_vf(v_ym1, b1, vl);
            vfloat32m1_t t4 = __riscv_vfmul_vf(v_ym2, b2, vl);

            vfloat32m1_t v_y1 = __riscv_vfadd_vv(t1, t2, vl);
            v_y1 = __riscv_vfadd_vv(v_y1, t3, vl);
            v_y1 = __riscv_vfadd_vv(v_y1, t4, vl);

            // Store y1
            __riscv_vse32_vf(&y1[i][j_vec], v_y1, vl);

            // Update state: xm1 = img, ym2 = ym1, ym1 = y1
            v_xm1 = v_img;
            v_ym2 = v_ym1;
            v_ym1 = v_y1;

            j_vec += vl;
        }
        #else
        for (j=0; j<_PB_H; j++) {
            y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2;
            xm1 = imgIn[i][j];
            ym2 = ym1;
            ym1 = y1[i][j];
        }
        #endif
    }

    // Backward pass along columns (j loop inside, reverse)
    for (i=0; i<_PB_W; i++) {
        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);
        xp1 = SCALAR_VAL(0.0);
        xp2 = SCALAR_VAL(0.0);

        #if defined(__riscv_vector)
        size_t vl;
        vfloat32m1_t v_yp1 = __riscv_vfmv_f_v(yp1);
        vfloat32m1_t v_yp2 = __riscv_vfmv_f_v(yp2);
        vfloat32m1_t v_xp1 = __riscv_vfmv_f_v(xp1);
        vfloat32m1_t v_xp2 = __riscv_vfmv_f_v(xp2);

        int j_vec = _PB_H - 1;
        while (j_vec >= 0) {
            vl = __riscv_vsetvl_e32m1(j_vec + 1);
            int start_j = j_vec - vl + 1;

            // Load imgIn[i][start_j:start_j+vl]
            vfloat32m1_t v_img = __riscv_vle32_vf(&imgIn[i][start_j], vl);

            // Compute: y2 = a3*xp1 + a4*xp2 + b1*yp1 + b2*yp2
            vfloat32m1_t t1 = __riscv_vfmul_vf(v_xp1, a3, vl);
            vfloat32m1_t t2 = __riscv_vfmul_vf(v_xp2, a4, vl);
            vfloat32m1_t t3 = __riscv_vfmul_vf(v_yp1, b1, vl);
            vfloat32m1_t t4 = __riscv_vfmul_vf(v_yp2, b2, vl);

            vfloat32m1_t v_y2 = __riscv_vfadd_vv(t1, t2, vl);
            v_y2 = __riscv_vfadd_vv(v_y2, t3, vl);
            v_y2 = __riscv_vfadd_vv(v_y2, t4, vl);

            // Store y2
            __riscv_vse32_vf(&y2[i][start_j], v_y2, vl);

            // Update state: xp2 = xp1, xp1 = img, yp2 = yp1, yp1 = y2
            v_xp2 = v_xp1;
            v_xp1 = v_img;
            v_yp2 = v_yp1;
            v_yp1 = v_y2;

            j_vec -= vl;
        }
        #else
        for (j=_PB_H-1; j>=0; j--) {
            y2[i][j] = a3*xp1 + a4*xp2 + b1*yp1 + b2*yp2;
            xp2 = xp1;
            xp1 = imgIn[i][j];
            yp2 = yp1;
            yp1 = y2[i][j];
        }
        #endif
    }

    // Combine y1 and y2 into imgOut
    for (i=0; i<_PB_W; i++)
        for (j=0; j<_PB_H; j++) {
            imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
        }

    // Forward pass along rows (i loop inside)
    for (j=0; j<_PB_H; j++) {
        tm1 = SCALAR_VAL(0.0);
        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);

        #if defined(__riscv_vector)
        size_t vl;
        vfloat32m1_t v_tm1 = __riscv_vfmv_f_v(tm1);
        vfloat32m1_t v_ym1 = __riscv_vfmv_f_v(ym1);
        vfloat32m1_t v_ym2 = __riscv_vfmv_f_v(ym2);

        int i_vec = 0;
        while (i_vec < _PB_W) {
            vl = __riscv_vsetvl_e32m1(_PB_W - i_vec);

            // Load imgOut[i_vec:i_vec+vl][j]
            vfloat32m1_t v_img = __riscv_vle32_vf(&imgOut[i_vec][j], vl);

            // Compute: y1 = a5*img + a6*tm1 + b1*ym1 + b2*ym2
            vfloat32m1_t t1 = __riscv_vfmul_vf(v_img, a5, vl);
            vfloat32m1_t t2 = __riscv_vfmul_vf(v_tm1, a6, vl);
            vfloat32m1_t t3 = __riscv_vfmul_vf(v_ym1, b1, vl);
            vfloat32m1_t t4 = __riscv_vfmul_vf(v_ym2, b2, vl);

            vfloat32m1_t v_y1 = __riscv_vfadd_vv(t1, t2, vl);
            v_y1 = __riscv_vfadd_vv(v_y1, t3, vl);
            v_y1 = __riscv_vfadd_vv(v_y1, t4, vl);

            // Store y1
            __riscv_vse32_vf(&y1[i_vec][j], v_y1, vl);

            // Update state: tm1 = img, ym2 = ym1, ym1 = y1
            v_tm1 = v_img;
            v_ym2 = v_ym1;
            v_ym1 = v_y1;

            i_vec += vl;
        }
        #else
        for (i=0; i<_PB_W; i++) {
            y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2;
            tm1 = imgOut[i][j];
            ym2 = ym1;
            ym1 = y1 [i][j];
        }
        #endif
    }

    // Backward pass along rows (i loop inside, reverse)
    for (j=0; j<_PB_H; j++) {
        tp1 = SCALAR_VAL(0.0);
        tp2 = SCALAR_VAL(0.0);
        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);

        #if defined(__riscv_vector)
        size_t vl;
        vfloat32m1_t v_tp1 = __riscv_vfmv_f_v(tp1);
        vfloat32m1_t v_tp2 = __riscv_vfmv_f_v(tp2);
        vfloat32m1_t v_yp1 = __riscv_vfmv_f_v(yp1);
        vfloat32m1_t v_yp2 = __riscv_vfmv_f_v(yp2);

        int i_vec = _PB_W - 1;
        while (i_vec >= 0) {
            vl = __riscv_vsetvl_e32m1(i_vec + 1);
            int start_i = i_vec - vl + 1;

            // Load imgOut[start_i:start_i+vl][j]
            vfloat32m1_t v_img = __riscv_vle32_vf(&imgOut[start_i][j], vl);

            // Compute: y2 = a7*tp1 + a8*tp2 + b1*yp1 + b2*yp2
            vfloat32m1_t t1 = __riscv_vfmul_vf(v_tp1, a7, vl);
            vfloat32m1_t t2 = __riscv_vfmul_vf(v_tp2, a8, vl);
            vfloat32m1_t t3 = __riscv_vfmul_vf(v_yp1, b1, vl);
            vfloat32m1_t t4 = __riscv_vfmul_vf(v_yp2, b2, vl);

            vfloat32m1_t v_y2 = __riscv_vfadd_vv(t1, t2, vl);
            v_y2 = __riscv_vfadd_vv(v_y2, t3, vl);
            v_y2 = __riscv_vfadd_vv(v_y2, t4, vl);

            // Store y2
            __riscv_vse32_vf(&y2[start_i][j], v_y2, vl);

            // Update state: tp2 = tp1, tp1 = img, yp2 = yp1, yp1 = y2
            v_tp2 = v_tp1;
            v_tp1 = v_img;
            v_yp2 = v_yp1;
            v_yp1 = v_y2;

            i_vec -= vl;
        }
        #else
        for (i=_PB_W-1; i>=0; i--) {
            y2[i][j] = a7*tp1 + a8*tp2 + b1*yp1 + b2*yp2;
            tp2 = tp1;
            tp1 = imgOut[i][j];
            yp2 = yp1;
            yp1 = y2[i][j];
        }
        #endif
    }

    // Final combination
    for (i=0; i<_PB_W; i++)
        for (j=0; j<_PB_H; j++)
            imgOut[i][j] = c2*(y1[i][j] + y2[i][j]);

#pragma endscop
}

