static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
 DATA_TYPE z[N];
 DATA_TYPE alpha;
 DATA_TYPE beta;
 DATA_TYPE sum;

 int i,k;

#pragma scop
 y[0] = -r[0];
 beta = SCALAR_VAL(1.0);
 alpha = -r[0];

 for (k = 1; k < _PB_N; k++) {
   beta = (1-alpha*alpha)*beta;
   sum = SCALAR_VAL(0.0);

   // Inner loop: sum += r[k-i-1]*y[i] for i=0..k-1
   #if defined(__riscv_vector)
   {
     size_t idx = 0;
     vfloat32m1_t v_sum = __riscv_vfmv_v_f(vf32m1(), 0.0f);

     while (idx < (size_t)k) {
       size_t len = __riscv_vsetvl_e32m1(k - idx);

       // Load y[idx : idx+len]
       vfloat32m1_t v_y = __riscv_vle32_v_f32m1(&y[idx], len);

       // Load r[k-1-idx : k-1-(idx+len)+1] reversed
       vfloat32m1_t v_r = __riscv_vle32_v_f32m1(&r[k - 1 - idx], len);

       // Reverse the r vector
       vfloat32m1_t v_r_rev = __riscv_vrev_v_f32m1(v_r, len);

       // Multiply and accumulate
       v_sum = __riscv_vfmacc_vv_f32m1(v_sum, v_y, v_r_rev, len);

       idx += len;
     }

     sum = __riscv_vfredosum_f32_m1(v_sum, 0.0f);
   }
   #else
   for (i=0; i<k; i++) {
      sum += r[k-i-1]*y[i];
   }
   #endif

   alpha = - (r[k] + sum)/beta;

   // Inner loop: z[i] = y[i] + alpha*y[k-i-1] for i=0..k-1
   #if defined(__riscv_vector)
   {
     size_t idx = 0;
     while (idx < (size_t)k) {
       size_t len = __riscv_vsetvl_e32m1(k - idx);

       // Load y[idx : idx+len]
       vfloat32m1_t v_y1 = __riscv_vle32_v_f32m1(&y[idx], len);

       // Load y[k-1-idx : k-1-(idx+len)+1] reversed
       vfloat32m1_t v_y2 = __riscv_vle32_v_f32m1(&y[k - 1 - idx], len);
       vfloat32m1_t v_y2_rev = __riscv_vrev_v_f32m1(v_y2, len);

       // Broadcast alpha
       vfloat32m1_t v_alpha = __riscv_vfmv_v_f_f32m1(alpha, len);

       // Compute: y1 + alpha * y2_rev
       vfloat32m1_t v_prod = __riscv_vfmul_vv_f32m1(v_alpha, v_y2_rev, len);
       vfloat32m1_t v_z = __riscv_vfadd_vv_f32m1(v_y1, v_prod, len);

       // Store result
       __riscv_vse32_v_f32m1(&z[idx], v_z, len);

       idx += len;
     }
   }
   #else
   for (i=0; i<k; i++) {
      z[i] = y[i] + alpha*y[k-i-1];
   }
   #endif

   // Copy z back to y
   #if defined(__riscv_vector)
   {
     size_t idx = 0;
     while (idx < (size_t)k) {
       size_t len = __riscv_vsetvl_e32m1(k - idx);
       vfloat32m1_t v_z_vec = __riscv_vle32_v_f32m1(&z[idx], len);
       __riscv_vse32_v_f32m1(&y[idx], v_z_vec, len);
       idx += len;
     }
   }
   #else
   for (i=0; i<k; i++) {
     y[i] = z[i];
   }
   #endif

   y[k] = alpha;
 }
#pragma endscop

}

