#include <riscv_vector.h>
#endif

static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

  for(t = 0; t < _PB_TMAX; t++)
    {
      // Update ey[0][j] = _fict_[t]
      #if defined(__riscv_vector)
      {
        size_t n = _PB_NY;
        while (n > 0) {
          size_t vl = __riscv_vsetvl_e32m1(n);
          vfloat32m1_t fill_vec = __riscv_vfmv_v_f(_fict_[t], vl);
          __riscv_vse32_v((DATA_TYPE*)ey[0], fill_vec, vl);
          n -= vl;
        }
      }
      #else
      for (j = 0; j < _PB_NY; j++)
	ey[0][j] = _fict_[t];
      #endif

      // Update ey[i][j] for i=1..NX-1
      for (i = 1; i < _PB_NX; i++)
	{
	  #if defined(__riscv_vector)
	  {
	    size_t n = _PB_NY;
	    const float half = SCALAR_VAL(0.5);
	    while (n > 0) {
	      size_t vl = __riscv_vsetvl_e32m1(n);
	      vfloat32m1_t hz_curr = __riscv_vle32_v((DATA_TYPE*)hz[i], vl);
	      vfloat32m1_t hz_prev = __riscv_vle32_v((DATA_TYPE*)hz[i-1], vl);
	      vfloat32m1_t diff = __riscv_vsub_vv(hz_curr, hz_prev, vl);
	      vfloat32m1_t scaled = __riscv_vfmul_vf(diff, half, vl);
	      vfloat32m1_t ey_curr = __riscv_vle32_v((DATA_TYPE*)ey[i], vl);
	      vfloat32m1_t result = __riscv_vsub_vv(ey_curr, scaled, vl);
	      __riscv_vse32_v((DATA_TYPE*)ey[i], result, vl);
	      n -= vl;
	    }
	  }
	  #else
	  for (j = 0; j < _PB_NY; j++)
	    ey[i][j] = ey[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i-1][j]);
	  #endif
	}

      // Update ex[i][j] for j=1..NY-1
      for (i = 0; i < _PB_NX; i++)
	{
	  #if defined(__riscv_vector)
	  {
	    size_t n = _PB_NY - 1;
	    if (n <= 0) continue;
	    const float half = SCALAR_VAL(0.5);
	    size_t offset = 1; // start from j=1
	    while (n > 0) {
	      size_t vl = __riscv_vsetvl_e32m1(n);
	      vfloat32m1_t hz_curr = __riscv_vle32_v((DATA_TYPE*)(hz[i] + offset), vl);
	      vfloat32m1_t hz_prev = __riscv_vle32_v((DATA_TYPE*)(hz[i] + offset - 1), vl);
	      vfloat32m1_t diff = __riscv_vsub_vv(hz_curr, hz_prev, vl);
	      vfloat32m1_t scaled = __riscv_vfmul_vf(diff, half, vl);
	      vfloat32m1_t ex_curr = __riscv_vle32_v((DATA_TYPE*)(ex[i] + offset), vl);
	      vfloat32m1_t result = __riscv_vsub_vv(ex_curr, scaled, vl);
	      __riscv_vse32_v((DATA_TYPE*)(ex[i] + offset), result, vl);
	      n -= vl;
	    }
	  }
	  #else
	  for (j = 1; j < _PB_NY; j++)
	    ex[i][j] = ex[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i][j-1]);
	  #endif
	}

      // Update hz[i][j] for i=0..NX-2, j=0..NY-2
      for (i = 0; i < _PB_NX - 1; i++)
	{
	  #if defined(__riscv_vector)
	  {
	    size_t n = _PB_NY - 1;
	    if (n <= 0) continue;
	    const float factor = SCALAR_VAL(0.7);
	    while (n > 0) {
	      size_t vl = __riscv_vsetvl_e32m1(n);
	      // ex[i][j+1] - ex[i][j]
	      vfloat32m1_t ex_next = __riscv_vle32_v((DATA_TYPE*)(ex[i] + 1), vl);
	      vfloat32m1_t ex_curr = __riscv_vle32_v((DATA_TYPE*)ex[i], vl);
	      vfloat32m1_t diff_ex = __riscv_vsub_vv(ex_next, ex_curr, vl);
	      // ey[i+1][j] - ey[i][j]
	      vfloat32m1_t ey_next = __riscv_vle32_v((DATA_TYPE*)ey[i+1], vl);
	      vfloat32m1_t ey_curr = __riscv_vle32_v((DATA_TYPE*)ey[i], vl);
	      vfloat32m1_t diff_ey = __riscv_vsub_vv(ey_next, ey_curr, vl);
	      // sum
	      vfloat32m1_t total_diff = __riscv_vadd_vv(diff_ex, diff_ey, vl);
	      vfloat32m1_t scaled = __riscv_vfmul_vf(total_diff, factor, vl);
	      vfloat32m1_t hz_curr = __riscv_vle32_v((DATA_TYPE*)hz[i], vl);
	      vfloat32m1_t result = __riscv_vsub_vv(hz_curr, scaled, vl);
	      __riscv_vse32_v((DATA_TYPE*)hz[i], result, vl);
	      n -= vl;
	    }
	  }
	  #else
	  for (j = 0; j < _PB_NY - 1; j++)
	    hz[i][j] = hz[i][j] - SCALAR_VAL(0.7)*  (ex[i][j+1] - ex[i][j] +
				       ey[i+1][j] - ey[i][j]);
	  #endif
	}
    }

#pragma endscop
}

