#include <riscv_vector.h>
#endif

static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      for(i = 0; i < _PB_N; i++)
	{
#ifdef __riscv_vector
	  // Load path[i][k] as a scalar to broadcast later
	  int32_t val_ik = path[i][k];

	  for (j = 0; j < _PB_N; )
	    {
	      size_t remaining = _PB_N - j;
	      size_t vl = __riscv_vsetvl_e32m1(remaining);

	      // Load path[i][j...j+vl-1]
	      vint32m1_t vec_path_ij = __riscv_vle32_v_i32(&path[i][j], vl);

	      // Load path[k][j...j+vl-1]
	      vint32m1_t vec_path_kj = __riscv_vle32_v_i32(&path[k][j], vl);

	      // Broadcast path[i][k] to vector
	      vint32m1_t vec_ik = __riscv_vmv_v_x_i32m1(val_ik, vl);

	      // Compute sum: path[i][k] + path[k][j]
	      vint32m1_t vec_sum = __riscv_vadd_vv_i32m1(vec_ik, vec_path_kj, vl);

	      // Compare: path[i][j] < sum
	      vbool32_t mask = __riscv_vlt_vv_b32_i32m1(vec_path_ij, vec_sum, vl);

	      // Select: min(path[i][j], sum) -> if mask is true (path[i][j] < sum), keep path[i][j], else take sum
	      // vmerge_vvm: if mask bit is 1, take 'val', else take 'mask_val'
	      // We want: if (path[i][j] < sum) ? path[i][j] : sum
	      // So if mask is true, we want path[i][j]. If false, we want sum.
	      vint32m1_t vec_result = __riscv_vmerge_vvm_i32m1(vec_path_ij, vec_sum, mask, vl);

	      // Store result back to path[i][j...]
	      __riscv_vse32_v_i32(&path[i][j], vec_result, vl);

	      j += vl;
	    }
#else
	  for (j = 0; j < _PB_N; j++)
	    path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
	      path[i][j] : path[i][k] + path[k][j];
#endif
	}
    }
#pragma endscop

}

