#include <riscv_vector.h>
#endif

static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    // Scale C[i][j] by beta using vectorization if possible
    #if defined(__riscv_vector)
    size_t vl_beta = __riscv_vsetvl_e32m1(_PB_NJ);
    vfloat32m1_t vbeta = __riscv_vfmv_f_v(beta, vl_beta);
    vfloat32m1_t vc = __riscv_vle32_vf(C[i], vl_beta);
    vc = __riscv_vfmul_vv(vc, vbeta, vl_beta);
    __riscv_vse32_vf(C[i], vc, vl_beta);
    #else
    for (j = 0; j < _PB_NJ; j++)
      C[i][j] *= beta;
    #endif

    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE a_val = A[i][k];
      #if defined(__riscv_vector)
      size_t vl_acc = __riscv_vsetvl_e32m1(_PB_NJ);
      vfloat32m1_t valpha = __riscv_vfmv_f_v(alpha, vl_acc);
      vfloat32m1_t va = __riscv_vfmv_f_v(a_val, vl_acc);
      vfloat32m1_t vb = __riscv_vle32_vf(B[k], vl_acc);
      vfloat32m1_t vprod = __riscv_vfmul_vv(va, vb, vl_acc);
      vprod = __riscv_vfmul_vv(vprod, valpha, vl_acc);
      vfloat32m1_t vc = __riscv_vle32_vf(C[i], vl_acc);
      vc = __riscv_vfadd_vv(vc, vprod, vl_acc);
      __riscv_vse32_vf(C[i], vc, vl_acc);
      #else
      for (j = 0; j < _PB_NJ; j++)
        C[i][j] += alpha * A[i][k] * B[k][j];
      #endif
    }
  }
#pragma endscop

}

