static
void kernel_gemver(int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

  // Loop 1: A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j]
  for (i = 0; i < _PB_N; i++) {
    #if defined(__riscv_vector)
      size_t vl;
      vfloat32m1_t vu1 = __riscv_vfmv_v_f(u1[i], 1);
      vfloat32m1_t vu2 = __riscv_vfmv_v_f(u2[i], 1);

      for (j = 0; j < _PB_N; ) {
        vl = __riscv_vsetvl_e32m1(_PB_N - j);
        if (vl == 0) break;

        vfloat32m1_t vv1 = __riscv_vle32f_v(&v1[j], vl);
        vfloat32m1_t vv2 = __riscv_vle32f_v(&v2[j], vl);
        vfloat32m1_t va = __riscv_vle32f_v(&A[i][j], vl);

        vfloat32m1_t term1 = __riscv_vfmul_vf(vu1, vv1, vl);
        vfloat32m1_t term2 = __riscv_vfmul_vf(vu2, vv2, vl);
        vfloat32m1_t sum = __riscv_vfadd_vv(term1, term2, vl);
        vfloat32m1_t res = __riscv_vfadd_vv(va, sum, vl);

        __riscv_vse32f_v(&A[i][j], res, vl);
        j += vl;
      }
    #else
      for (j = 0; j < _PB_N; j++)
        A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j];
    #endif
  }

  // Loop 2: x[i] = x[i] + beta * A[j][i] * y[j]
  for (i = 0; i < _PB_N; i++) {
    #if defined(__riscv_vector)
      size_t vl;
      vfloat32m1_t vx_init = __riscv_vfmv_v_f(x[i], 1);

      for (j = 0; j < _PB_N; ) {
        vl = __riscv_vsetvl_e32m1(_PB_N - j);
        if (vl == 0) break;

        vfloat32m1_t vy = __riscv_vle32f_v(&y[j], vl);
        vfloat32m1_t va_col = __riscv_vle32f_v(&A[j][i], vl);

        vfloat32m1_t prod = __riscv_vfmul_vv(va_col, vy, vl);
        vfloat32m1_t scaled = __riscv_vfmul_vf(prod, beta, vl);

        vx_init = __riscv_vfadd_vf(vx_init, scaled, vl);
        j += vl;
      }
      x[i] = __riscv_vmv_f_s(vx_init);
    #else
      for (j = 0; j < _PB_N; j++)
        x[i] = x[i] + beta * A[j][i] * y[j];
    #endif
  }

  // Loop 3: x[i] = x[i] + z[i]
  #if defined(__riscv_vector)
    size_t vl = __riscv_vsetvl_e32m1(_PB_N);
    vfloat32m1_t vx = __riscv_vle32f_v(x, vl);
    vfloat32m1_t vz = __riscv_vle32f_v(z, vl);
    vfloat32m1_t vx_res = __riscv_vfadd_vv(vx, vz, vl);
    __riscv_vse32f_v(x, vx_res, vl);
  #else
    for (i = 0; i < _PB_N; i++)
      x[i] = x[i] + z[i];
  #endif

  // Loop 4: w[i] = w[i] + alpha * A[i][j] * x[j]
  for (i = 0; i < _PB_N; i++) {
    #if defined(__riscv_vector)
      size_t vl;
      vfloat32m1_t vw_init = __riscv_vfmv_v_f(w[i], 1);

      for (j = 0; j < _PB_N; ) {
        vl = __riscv_vsetvl_e32m1(_PB_N - j);
        if (vl == 0) break;

        vfloat32m1_t va_row = __riscv_vle32f_v(&A[i][j], vl);
        vfloat32m1_t vx_vec = __riscv_vle32f_v(&x[j], vl);

        vfloat32m1_t prod = __riscv_vfmul_vv(va_row, vx_vec, vl);
        vfloat32m1_t scaled = __riscv_vfmul_vf(prod, alpha, vl);

        vw_init = __riscv_vfadd_vf(vw_init, scaled, vl);
        j += vl;
      }
      w[i] = __riscv_vmv_f_s(vw_init);
    #else
      for (j = 0; j < _PB_N; j++)
        w[i] = w[i] + alpha * A[i][j] * x[j];
    #endif
  }

#pragma endscop
}

