static
void kernel_gramschmidt(int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;

  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      nrm = SCALAR_VAL(0.0);

#if defined(__riscv_vector)
      // Determine vector length based on element type
      size_t vl_m = __riscv_vsetvl_e32m1(m);
      vfloat32m1_t v_nrm = __riscv_vfsgnjx_vf_f32m1(v_nrm, SCALAR_VAL(0.0), vl_m);

      // Vectorized dot product: nrm += A[i][k] * A[i][k]
      for (i = 0; i < m; i += vl_m) {
        size_t vl = __riscv_vsetvl_e32m1(m - i);
        vfloat32m1_t vec_a = __riscv_vle32_v_f32m1((const float*)&A[i][k], vl);
        vfloat32m1_t vec_sq = __riscv_vfmul_vv_f32m1(vec_a, vec_a, vl);
        v_nrm = __riscv_vfredosum_vs_f32m1_f32m1(v_nrm, vec_sq, vl);
      }
      nrm = __riscv_vfmv_s_f_f32m1(v_nrm);
#else
      for (i = 0; i < _PB_M; i++)
        nrm += A[i][k] * A[i][k];
#endif

      R[k][k] = SQRT_FUN(nrm);
      DATA_TYPE inv_rkk = SCALAR_VAL(1.0) / R[k][k];

#if defined(__riscv_vector)
      size_t vl_m_q = __riscv_vsetvl_e32m1(m);
      vfloat32m1_t v_inv_rkk = __riscv_vfmv_v_f_f32m1(inv_rkk, vl_m_q);

      // Vectorized Q[i][k] = A[i][k] / R[k][k]
      for (i = 0; i < m; i += vl_m_q) {
        size_t vl = __riscv_vsetvl_e32m1(m - i);
        vfloat32m1_t vec_a = __riscv_vle32_v_f32m1((const float*)&A[i][k], vl);
        vfloat32m1_t vec_q = __riscv_vfmul_vv_f32m1(vec_a, v_inv_rkk, vl);
        __riscv_vse32_v_f32m1((float*)&Q[i][k], vec_q, vl);
      }
#else
      for (i = 0; i < _PB_M; i++)
        Q[i][k] = A[i][k] / R[k][k];
#endif

      for (j = k + 1; j < _PB_N; j++)
	{
	  R[k][j] = SCALAR_VAL(0.0);

#if defined(__riscv_vector)
          size_t vl_m_dot = __riscv_vsetvl_e32m1(m);
          vfloat32m1_t v_rkj = __riscv_vfsgnjx_vf_f32m1(v_rkj, SCALAR_VAL(0.0), vl_m_dot);

          // Load Q column k once for reuse
          vfloat32m1_t vec_q_k;
          if (m > 0) {
              size_t vl_load = __riscv_vsetvl_e32m1(m);
              vec_q_k = __riscv_vle32_v_f32m1((const float*)&Q[0][k], vl_load);
          }

          // Vectorized dot product: R[k][j] += Q[i][k] * A[i][j]
          for (i = 0; i < m; i += vl_m_dot) {
            size_t vl = __riscv_vsetvl_e32m1(m - i);
            vfloat32m1_t vec_a_j = __riscv_vle32_v_f32m1((const float*)&A[i][j], vl);
            vfloat32m1_t vec_prod = __riscv_vfmul_vv_f32m1(vec_q_k, vec_a_j, vl);
            v_rkj = __riscv_vfredosum_vs_f32m1_f32m1(v_rkj, vec_prod, vl);
          }
          R[k][j] = __riscv_vfmv_s_f_f32m1(v_rkj);

          // Vectorized update: A[i][j] = A[i][j] - Q[i][k] * R[k][j]
          vfloat32m1_t v_rkj_val = __riscv_vfmv_v_f_f32m1(R[k][j], vl_m_dot);
          for (i = 0; i < m; i += vl_m_dot) {
            size_t vl = __riscv_vsetvl_e32m1(m - i);
            vfloat32m1_t vec_a_j_curr = __riscv_vle32_v_f32m1((const float*)&A[i][j], vl);
            vfloat32m1_t vec_q_k_curr = __riscv_vle32_v_f32m1((const float*)&Q[i][k], vl);
            vfloat32m1_t vec_sub = __riscv_vfmul_vv_f32m1(vec_q_k_curr, v_rkj_val, vl);
            vfloat32m1_t vec_res = __riscv_vfsub_vv_f32m1(vec_a_j_curr, vec_sub, vl);
            __riscv_vse32_v_f32m1((float*)&A[i][j], vec_res, vl);
          }
#else
	  for (i = 0; i < _PB_M; i++)
	    R[k][j] += Q[i][k] * A[i][j];
	  for (i = 0; i < _PB_M; i++)
	    A[i][j] = A[i][j] - Q[i][k] * R[k][j];
#endif
	}
    }
#pragma endscop

}

