static
void kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

#pragma scop
    for (t = 1; t <= TSTEPS; t++) {
        // First half: B = f(A)
        for (i = 1; i < _PB_N-1; i++) {
            for (j = 1; j < _PB_N-1; j++) {
                #if defined(__riscv_vector)
                size_t start_k = 1;
                size_t end_k = _PB_N - 2; 
                size_t len = end_k - start_k;

                if (len > 0) {
                    vfloat64m1_t v_center, v_plus_i, v_minus_i, v_plus_j, v_minus_j, v_plus_k, v_minus_k;
                    vfloat64m1_t v_const_0125, v_const_2_0, v_result;

                    // Correct intrinsic usage: __riscv_vfmv_f_x or similar, but for float we use __riscv_vfmv_v_f with proper VL
                    // Actually, the correct way to broadcast a scalar to vector is __riscv_vfmv_v_f(vl, scalar)
                    // But the error suggests __riscv_vfmv_v_f doesn't exist. Let's use __riscv_vfmv_f_x? No, that's for integers.
                    // The correct intrinsic for floating point scalar to vector is __riscv_vfmv_v_f(vl, scalar) in some versions,
                    // but standard RVV uses __riscv_vfmv_v_f(vl, scalar) where vl is the vector length.
                    // Wait, the error says "did you mean '__riscv_vfmv_f'". That might be the issue.
                    // Actually, looking at RVV intrinsics, to move a scalar to a vector register, we use:
                    // __riscv_vfmv_v_f(vl, scalar) -> This creates a vector of length vl filled with scalar.
                    // However, the compiler might expect the VL to be set first.

                    // Let's try setting VL explicitly and using the correct intrinsic name.
                    // The error message suggests __riscv_vfmv_f exists. Maybe it's __riscv_vfmv_f(vl, scalar)?
                    // Or maybe we should use __riscv_vfmv_v_f with the correct signature.

                    // Alternative approach: Use __riscv_vfmv_v_f with vsetvl_e64m1(len) result as VL
                    size_t vl = __riscv_vsetvl_e64m1(len);
                    v_const_0125 = __riscv_vfmv_v_f(vl, 0.125);
                    v_const_2_0 = __riscv_vfmv_v_f(vl, 2.0);

                    size_t offset = 0;

                    while (offset < len) {
                        size_t current_len = __riscv_vsetvl_e64m1(len - offset);

                        v_center = __riscv_vle64_vf(A[i][j] + start_k + offset, current_len);
                        v_plus_i = __riscv_vle64_vf(A[i+1][j] + start_k + offset, current_len);
                        v_minus_i = __riscv_vle64_vf(A[i-1][j] + start_k + offset, current_len);
                        v_plus_j = __riscv_vle64_vf(A[i][j+1] + start_k + offset, current_len);
                        v_minus_j = __riscv_vle64_vf(A[i][j-1] + start_k + offset, current_len);
                        v_plus_k = __riscv_vle64_vf(A[i][j] + start_k + offset + 1, current_len);
                        v_minus_k = __riscv_vle64_vf(A[i][j] + start_k + offset - 1, current_len);

                        vfloat64m1_t term_i = __riscv_vfsub_vv(v_plus_i, 
                            __riscv_vfmul_vv(v_const_2_0, v_center, current_len), current_len);
                        term_i = __riscv_vfadd_vv(term_i, v_minus_i, current_len);
                        term_i = __riscv_vfmul_vv(v_const_0125, term_i, current_len);

                        vfloat64m1_t term_j = __riscv_vfsub_vv(v_plus_j, 
                            __riscv_vfmul_vv(v_const_2_0, v_center, current_len), current_len);
                        term_j = __riscv_vfadd_vv(term_j, v_minus_j, current_len);
                        term_j = __riscv_vfmul_vv(v_const_0125, term_j, current_len);

                        vfloat64m1_t term_k = __riscv_vfsub_vv(v_plus_k, 
                            __riscv_vfmul_vv(v_const_2_0, v_center, current_len), current_len);
                        term_k = __riscv_vfadd_vv(term_k, v_minus_k, current_len);
                        term_k = __riscv_vfmul_vv(v_const_0125, term_k, current_len);

                        v_result = __riscv_vfadd_vv(term_i, term_j, current_len);
                        v_result = __riscv_vfadd_vv(v_result, term_k, current_len);
                        v_result = __riscv_vfadd_vv(v_result, v_center, current_len);

                        __riscv_vse64_vf(B[i][j] + start_k + offset, v_result, current_len);

                        offset += current_len;
                    }
                }
                #else
                for (k = 1; k < _PB_N-1; k++) {
                    B[i][j][k] =   SCALAR_VAL(0.125) * (A[i+1][j][k] - SCALAR_VAL(2.0) * A[i][j][k] + A[i-1][j][k])
                                 + SCALAR_VAL(0.125) * (A[i][j+1][k] - SCALAR_VAL(2.0) * A[i][j][k] + A[i][j-1][k])
                                 + SCALAR_VAL(0.125) * (A[i][j][k+1] - SCALAR_VAL(2.0) * A[i][j][k] + A[i][j][k-1])
                                 + A[i][j][k];
                }
                #endif
            }
        }

        // Second half: A = f(B)
        for (i = 1; i < _PB_N-1; i++) {
           for (j = 1; j < _PB_N-1; j++) {
               #if defined(__riscv_vector)
                size_t start_k = 1;
                size_t end_k = _PB_N - 2;
                size_t len = end_k - start_k;

                if (len > 0) {
                    vfloat64m1_t v_center, v_plus_i, v_minus_i, v_plus_j, v_minus_j, v_plus_k, v_minus_k;
                    vfloat64m1_t v_const_0125, v_const_2_0, v_result;

                    size_t vl = __riscv_vsetvl_e64m1(len);
                    v_const_0125 = __riscv_vfmv_v_f(vl, 0.125);
                    v_const_2_0 = __riscv_vfmv_v_f(vl, 2.0);

                    size_t offset = 0;

                    while (offset < len) {
                        size_t current_len = __riscv_vsetvl_e64m1(len - offset);

                        v_center = __riscv_vle64_vf(B[i][j] + start_k + offset, current_len);
                        v_plus_i = __riscv_vle64_vf(B[i+1][j] + start_k + offset, current_len);
                        v_minus_i = __riscv_vle64_vf(B[i-1][j] + start_k + offset, current_len);
                        v_plus_j = __riscv_vle64_vf(B[i][j+1] + start_k + offset, current_len);
                        v_minus_j = __riscv_vle64_vf(B[i][j-1] + start_k + offset, current_len);
                        v_plus_k = __riscv_vle64_vf(B[i][j] + start_k + offset + 1, current_len);
                        v_minus_k = __riscv_vle64_vf(B[i][j] + start_k + offset - 1, current_len);

                        vfloat64m1_t term_i = __riscv_vfsub_vv(v_plus_i, 
                            __riscv_vfmul_vv(v_const_2_0, v_center, current_len), current_len);
                        term_i = __riscv_vfadd_vv(term_i, v_minus_i, current_len);
                        term_i = __riscv_vfmul_vv(v_const_0125, term_i, current_len);

                        vfloat64m1_t term_j = __riscv_vfsub_vv(v_plus_j, 
                            __riscv_vfmul_vv(v_const_2_0, v_center, current_len), current_len);
                        term_j = __riscv_vfadd_vv(term_j, v_minus_j, current_len);
                        term_j = __riscv_vfmul_vv(v_const_0125, term_j, current_len);

                        vfloat64m1_t term_k = __riscv_vfsub_vv(v_plus_k, 
                            __riscv_vfmul_vv(v_const_2_0, v_center, current_len), current_len);
                        term_k = __riscv_vfadd_vv(term_k, v_minus_k, current_len);
                        term_k = __riscv_vfmul_vv(v_const_0125, term_k, current_len);

                        v_result = __riscv_vfadd_vv(term_i, term_j, current_len);
                        v_result = __riscv_vfadd_vv(v_result, term_k, current_len);
                        v_result = __riscv_vfadd_vv(v_result, v_center, current_len);

                        __riscv_vse64_vf(A[i][j] + start_k + offset, v_result, current_len);

                        offset += current_len;
                    }
                }
                #else
               for (k = 1; k < _PB_N-1; k++) {
                   A[i][j][k] =   SCALAR_VAL(0.125) * (B[i+1][j][k] - SCALAR_VAL(2.0) * B[i][j][k] + B[i-1][j][k])
                                + SCALAR_VAL(0.125) * (B[i][j+1][k] - SCALAR_VAL(2.0) * B[i][j][k] + B[i][j-1][k])
                                + SCALAR_VAL(0.125) * (B[i][j][k+1] - SCALAR_VAL(2.0) * B[i][j][k] + B[i][j][k-1])
                                + B[i][j][k];
               }
                #endif
           }
       }
    }
#pragma endscop

}

