            // Compute sum and multiply by constant
            vfloat64m1_t sum = __riscv_vfadd_vv(a_prev, a_curr, vl);
            sum = __riscv_vfadd_vv(sum, a_next, vl);
            vfloat64m1_t result = __riscv_vfmul_vf(sum, const_val, vl);

            // Store to B
            __riscv_vse64_v_f64m1(&B[start + offset], result, vl);

            offset += vl;
            vl = __riscv_vsetvl_e64m1(len - offset);
