	      vfloat32m1_t a_up = __riscv_vle32_vf((const float *)(A[i-1] + j), vl);
	      vfloat32m1_t a_down = __riscv_vle32_vf((const float *)(A[i+1] + j), vl);

	      vfloat32m1_t sum = __riscv_vadd_vv(a_curr, a_left, vl);
	      sum = __riscv_vadd_vv(sum, a_right, vl);
	      sum = __riscv_vadd_vv(sum, a_up, vl);
	      sum = __riscv_vadd_vv(sum, a_down, vl);

	      vfloat32m1_t result = __riscv_vfmul_vf(sum, scalar_val, vl);

	      __riscv_vse32_vf((float *)(B[i] + j), result, vl);
	    }

	  // Handle remaining elements with scalar loop
	  for (; j < _PB_N - 1; j++)
	    {
	      B[i][j] = SCALAR_VAL(0.2) * (A[i][j] + A[i][j-1] + A[i][1+j] + A[1+i][j] + A[i-1][j]);
	    }
	  #else
	  for (j = 1; j < _PB_N - 1; j++)
	    {
	      B[i][j] = SCALAR_VAL(0.2) * (A[i][j] + A[i][j-1] + A[i][1+j] + A[1+i][j] + A[i-1][j]);
	    }
	  #endif
	}

      // Second sweep: A[i][j] = 0.2 * (B[i][j] + B[i][j-1] + B[i][j+1] + B[i+1][j] + B[i-1][j])
      for (i = 1; i < _PB_N - 1; i++)
	{
	  #if defined(__riscv_vector)
	  size_t vl = __riscv_vsetvl_e32m1(_PB_N - 2);
	  float scalar_val = SCALAR_VAL(0.2);

	  // Process vectorized portion
	  for (j = 1; j <= _PB_N - 2 - (int)vl; j += (int)vl)
	    {
	      vfloat32m1_t b_curr = __riscv_vle32_vf((const float *)(B[i] + j), vl);
	      vfloat32m1_t b_left = __riscv_vle32_vf((const float *)(B[i] + j - 1), vl);
	      vfloat32m1_t b_right = __riscv_vle32_vf((const float *)(B[i] + j + 1), vl);
	      vfloat32m1_t b_up = __riscv_vle32_vf((const float *)(B[i-1] + j), vl);
	      vfloat32m1_t b_down = __riscv_vle32_vf((const float *)(B[i+1] + j), vl);

	      vfloat32m1_t sum = __riscv_vadd_vv(b_curr, b_left, vl);
	      sum = __riscv_vadd_vv(sum, b_right, vl);
	      sum = __riscv_vadd_vv(sum, b_up, vl);
	      sum = __riscv_vadd_vv(sum, b_down, vl);

	      vfloat32m1_t result = __riscv_vfmul_vf(sum, scalar_val, vl);

	      __riscv_vse32_vf((float *)(A[i] + j), result, vl);
	    }

	  // Handle remaining elements with scalar loop
	  for (; j < _PB_N - 1; j++)
	    {
	      A[i][j] = SCALAR_VAL(0.2) * (B[i][j] + B[i][j-1] + B[i][1+j] + B[1+i][j] + B[i-1][j]);
	    }
	  #else
	  for (j = 1; j < _PB_N - 1; j++)
	    {
	      A[i][j] = SCALAR_VAL(0.2) * (B[i][j] + B[i][j-1] + B[i][1+j] + B[1+i][j] + B[i-1][j]);
