static
void kernel_mvt(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#pragma scop
  // First loop: x1[i] += A[i][j] * y_1[j] (Matrix-Vector multiply)
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE acc = 0.0;
    #if defined(__riscv_vector)
    size_t vl;
    vfloat32m1_t vec_acc = __riscv_vfmv_v_f(0.0f, 8);

    // Process in vector chunks
    for (j = 0; j < _PB_N; j += 8) {
      size_t remaining = _PB_N - j;
      if (remaining <= 8) {
        vl = remaining;
      } else {
        vl = 8;
      }

      vfloat32m1_t vec_y = __riscv_vle32_v_f32(&y_1[j], vl);
      vfloat32m1_t vec_a = __riscv_vle32_v_f32(&A[i][j], vl);
      vfloat32m1_t vec_prod = __riscv_vfmul_vv_f32(vec_a, vec_y, vl);
      vec_acc = __riscv_vfadd_vv_f32(vec_acc, vec_prod, vl);
    }

    // Reduce vector accumulator to scalar
    acc = __riscv_vfredosum_vs_f32_f32(vec_acc, 0.0f, 8);
    #else
    for (j = 0; j < _PB_N; j++) {
      acc += A[i][j] * y_1[j];
    }
    #endif
    x1[i] = x1[i] + acc;
  }

  // Second loop: x2[i] += A[j][i] * y_2[j] (Transpose Matrix-Vector multiply)
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE acc = 0.0;
    #if defined(__riscv_vector)
    size_t vl;
    vfloat32m1_t vec_acc = __riscv_vfmv_v_f(0.0f, 8);

    // Process in vector chunks
    for (j = 0; j < _PB_N; j += 8) {
      size_t remaining = _PB_N - j;
      if (remaining <= 8) {
        vl = remaining;
      } else {
        vl = 8;
      }

      vfloat32m1_t vec_y = __riscv_vle32_v_f32(&y_2[j], vl);
      // Access column i of matrix A (stride is N)
      vfloat32m1_t vec_a = __riscv_vle32_v_f32_stride(&A[0][i], N, vl);
      vfloat32m1_t vec_prod = __riscv_vfmul_vv_f32(vec_a, vec_y, vl);
      vec_acc = __riscv_vfadd_vv_f32(vec_acc, vec_prod, vl);
    }

    // Reduce vector accumulator to scalar
    acc = __riscv_vfredosum_vs_f32_f32(vec_acc, 0.0f, 8);
    #else
    for (j = 0; j < _PB_N; j++) {
      acc += A[j][i] * y_2[j];
    }
    #endif
    x2[i] = x2[i] + acc;
  }
#pragma endscop

}

