		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    // Scale C[i][0..i] by beta
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;

    // Vectorized accumulation over k and j
    // We vectorize over the innermost dimension where possible.
    // The loop structure is: for k, for j<=i: C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k]
    // This can be rewritten as: C[i][j] += alpha * (A[j][k]*B[i][k] + B[j][k]*A[i][k])

    // For RISC-V V, we can vectorize over 'j' if we process multiple rows of A and B at once.
    // However, the dependency on 'i' being fixed and 'j' going up to 'i' makes it a triangular region.
    // Let's try to vectorize over 'k' first? No, 'k' is the outer loop in the original code for the accumulation part.
    // Actually, let's look at the data access patterns:
    // A[j][k], B[j][k] vary with j (column k of A and B).
    // A[i][k], B[i][k] are constant for a fixed i and k.
    // So for a fixed i and k, we are updating C[i][0..i] using column k of A and B.

    // Strategy: Vectorize over 'j' (the row index within the triangle) for each 'k'.
    // But 'j' goes from 0 to i. The length varies.
    // We can use RVV dynamic lengths.

    for (k = 0; k < _PB_M; k++) {
      // Precompute constants for this k
      DATA_TYPE Ai_k = A[i][k];
      DATA_TYPE Bi_k = B[i][k];

      // We need to update C[i][j] for j=0..i
      // C[i][j] += alpha * (A[j][k]*Bi_k + B[j][k]*Ai_k)

      // Determine vector length
      size_t vl = i + 1;
